fn solve(s: Vec<char>) -> &'static str {
    let mut stack: Vec<char> = Vec::with_capacity(s.len());
    let mut removals: usize = 0;

    for c in s {
        if let Some(&top) = stack.last() {
            if top == c {
                // found a pair, remove it
                stack.pop();
                removals += 1;
                continue;
            }
        }
        // no pair, push current character
        stack.push(c);
    }

    if removals % 2 == 1 {
        "Yes"
    } else {
        "No"
    }
}